{"content": "import pytest
from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(name: Optional[str] = Form(None)):
    return {"name": name}

client = TestClient(app)

def test_empty_form_value():
    # When name is sent as an empty string, it should be interpreted as None if default is None
    # because of how HTML forms work and how FastAPI handles them.
    # If the fix is working, it should return {"name": None} or whatever the default is.
    # If the bug is present, it might return {"name": ""} or fail validation if it was not Optional.

    # For Optional[str] = Form(None), an empty string should be treated as None.
    response = client.post("/test", data={"name": ""})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_missing_form_value():
    response = client.post("/test", data={})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_provided_form_value():
    response = client.post("/test", data={"name": "foo"})
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

if __name__ == "__main__":
    pytest.main([__file__])
